update tb_content
content_type=#{contentType}, title=#{title}, content=#{content}, audit_status=#{auditStatus}, update_time=#{updateTime},
where content_id=#{contentId}

UPDATE tb_content_report
status = #{status}, handler_id = #{handlerId}, handle_result = #{handleResult}, handle_remark = #{handleRemark}, handle_time = #{handleTime}, update_time = #{updateTime},
WHERE id = #{id}

mapper.select:
SELECT c.content_id, c.content_type, c.title, IF(CHAR_LENGTH(c.content) > 100, CONCAT(LEFT(c.content, 100), '...'), c.content) AS content, c.publish_user_id, c.audit_status, c.create_time, c.update_time, c.liked, c.comment_count, c.collect_count, c.is_deleted FROM tb_content c WHERE c.content_id IN
#{id}
and c.is_deleted = 0 and c.audit_status = 1 ORDER BY FIELD(c.content_id,
#{id}
)

SELECT * FROM tb_content
WHERE publish_user_id = #{userId}
AND is_deleted = 0

    AND audit_status = #{auditStatus}

ORDER BY create_time DESC

select * from tb_content where is_deleted = 0 AND audit_status=1 AND (title like CONCAT('%',#{keyword},'%') or content like CONCAT('%',#{keyword},'%'))
AND content_type = #{contentType}
order by create_time desc

